\end{equation}

where

\begin{align}\label{3.16}
\widetilde{\varphi}(t)&=\widehat{\varphi}(t)+\int_{0}^{t}\widetilde{P}(t,s)\widehat{\varphi}
(s)ds, \nonumber \\
