\end{align}

and

\begin{eqnarray}\label{3.17}
\widetilde{P}(t,s) = \sum\limits_{k=1}^{\infty
}\widetilde{\Lambda}^{k}(t,s), \quad \widetilde{\Lambda}^{1}(t,s)
=\widehat{f}(t,s), \quad
\widetilde{\Lambda}^{k+1}(t,s)=\int_{s}^{t}\widehat{f}(t,r)\widetilde{\Lambda}^{k}(r,s)dr.
\end{eqnarray}

Note that the technique applied here is similar to that in (\ref{3.5.1}). To summarize, we have the following theorem.

