&-\frac{1}{R}\int_0^T\int_0^{s\wedge t}\widehat{c}(t,r)\widehat{c}(s,r)\dbE^{\mathcal{F}_r}[x_i(s)-\overline{x}_i(s)]drds.
\end{align*}

Therefore,

\begin{align*}
x^{N}(t)-\widehat{a}(t)=& \; \overline{x}^{N}(t)-\widehat{a}(t)+\int_0^t\widehat{f}(t,s)\Big[x^{N}(s)-\widehat{a}(s)\Big]ds\nonumber\\
& - \frac 1 R \int_0^T\int_0^{s\wedge
t}\widehat{c}(t,r)\widehat{c}(s,r)\dbE^{\mathcal{F}_r}[x^N(s)-\widehat{a}(s)]drds\nonumber\\
